class SimpleBloomFilter {
    private HashSet<Integer> bits = new HashSet<>();
    private int size = 100;

    private int hash1(String s) { return Math.abs(s.hashCode() % size); }
    private int hash2(String s) { return Math.abs((s.hashCode() * 31) % size); }

    void add(String s) {
        bits.add(hash1(s));
        bits.add(hash2(s));
    }

    boolean mightContain(String s) {
        return bits.contains(hash1(s)) && bits.contains(hash2(s));
    }
}

