class ConsistentHashRing {
    private TreeSet<Integer> ring = new TreeSet<>();

    void addNode(int id) { ring.add(id); }
    void removeNode(int id) { ring.remove(id); }

    Integer getNode(int key) {
        Integer node = ring.ceiling(key);
        return node != null ? node : ring.first();
    }
}

