    List<Integer> subset = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        if ((mask & (1 << i)) != 0) subset.add(arr[i]);
    }
    Collections.sort(subset);
    uniqueSubsets.add(subset);
}
